def lower_bound(values: list[int], target: int) -> int:
    """Return the first position whose value is at least target."""
    left = 0
    right = len(values)

    # Everything before left is strictly smaller than target.
    # Every position at or beyond right is already a candidate.
    while left < right:
        middle = left + (right - left) // 2
        if values[middle] < target:
            left = middle + 1
        else:
            right = middle

    return left


def equal_range(values: list[int], target: int) -> tuple[int, int]:
    """Return the half-open interval covering all integer matches."""
    first = lower_bound(values, target)
    after_last = lower_bound(values, target + 1)
    return first, after_last


def demo() -> None:
    samples = [
        ([], 7, (0, 0)),
        ([2, 4, 4, 4, 7], 4, (1, 4)),
        ([2, 4, 4, 4, 7], 5, (4, 4)),
        ([2, 4, 4, 4, 7], 8, (5, 5)),
    ]

    for values, target, expected in samples:
        actual = equal_range(values, target)
        if actual != expected:
            raise AssertionError(f"{values!r}, {target}: expected {expected}, got {actual}")


if __name__ == "__main__":
    demo()
